"""Private worker entrypoint. Input is generated by the server, never by a client."""

import pickle
import sys

from app.core.exceptions import AppError


def main() -> None:
    function, args, kwargs = pickle.loads(sys.stdin.buffer.read())
    try:
        result = {"ok": True, "value": function(*args, **kwargs)}
    except AppError as exc:
        result = {"ok": False, "message": exc.message, "code": exc.code}
    except Exception:
        result = {
            "ok": False,
            "message": "文件处理失败，请检查文件格式、编码或是否损坏",
            "code": 4025,
        }
    sys.stdout.buffer.write(pickle.dumps(result))


if __name__ == "__main__":
    main()
